// Abstract animals eat and sleep
public class Q09 {abstract static class Animal {abstract void eat();abstract void sleep();}static class Lion extends Animal {void eat(){System.out.println("Lion eats meat");}void sleep(){System.out.println("Lion rests in pride");}}static class Tiger extends Animal {void eat(){System.out.println("Tiger hunts prey");}void sleep(){System.out.println("Tiger rests alone");}}static class Deer extends Animal {void eat(){System.out.println("Deer grazes grass");}void sleep(){System.out.println("Deer sleeps alertly");}}public static void main(String[] args){for(Animal a:new Animal[]{new Lion(),new Tiger(),new Deer()}){a.eat();a.sleep();}}}
